fn gcd_i(mut m: i32, mut n: i32) -> i32 {
    // Since m and n are strictly positive, we can apply the
    // subtraction-based Euclidean algorithm safely.
    while m != n {
        if m > n {
            m -= n;
        } else {
            n -= m;
        }
    }
    // When they become equal, that's the GCD.
    m
}

